import cases from './__fixtures__/csv-files-cases.json';
import {
  classesToCsv,
  guardiansToCsv,
  membershipsToCsv,
  requirementsToCsv,
  roomTypesToCsv,
  roomsToCsv,
  studentsToCsv,
  subjectsToCsv,
  teacherDutiesToCsv,
  teacherQualificationsToCsv,
  teachersToCsv,
  timplanToCsv,
} from './csv-files';
import { serializeCsv } from './csv-writer';

/**
 * The gateway's copies of the web's CSV writers against the bytes the web's
 * writers wrote for the same inputs: __fixtures__/csv-files-cases.json is
 * generated by web/lib/csv-files-cases.test.ts and replayed here and there.
 * See csv-files.ts for why the gateway copies them.
 */

type Args = any[]; // eslint-disable-line @typescript-eslint/no-explicit-any

const adapters: Record<string, (args: Args) => string> = {
  serializeCsv: ([headers, rows]) => serializeCsv(headers, rows),
  roomTypesToCsv: ([types]) => roomTypesToCsv(types),
  subjectsToCsv: ([subjects, names]) => subjectsToCsv(subjects, (id: string | null) => (id ? (names[id] ?? '') : '')),
  roomsToCsv: ([rooms, types]) => roomsToCsv(rooms, types),
  classesToCsv: ([groups, subjects]) => classesToCsv(groups, subjects),
  teachersToCsv: ([people, employments]) => teachersToCsv(people, employments === null ? undefined : (id: string) => employments[id]),
  teacherQualificationsToCsv: ([rows, people, subjects]) => teacherQualificationsToCsv(rows, people, subjects),
  studentsToCsv: ([people, names]) => studentsToCsv(people, (id: string | null) => (id ? (names[id] ?? '') : '')),
  membershipsToCsv: ([groups, people, memberships]) => membershipsToCsv(groups, people, memberships),
  teacherDutiesToCsv: ([duties, people, subjects, groups]) => teacherDutiesToCsv(duties, people, subjects, groups),
  requirementsToCsv: ([requirements, groups, subjects, people]) => requirementsToCsv(requirements, groups, subjects, people),
  guardiansToCsv: ([rows]) => guardiansToCsv(rows),
  timplanToCsv: ([entries, subjects]) => timplanToCsv(entries, subjects),
};

describe("the gateway's CSV writers write the web's bytes", () => {
  it('replays a case for every builder', () => {
    expect(new Set(cases.cases.map((c) => c.builder))).toEqual(new Set(Object.keys(adapters)));
  });

  it.each(cases.cases.map((c) => [c.name, c] as const))('%s', (_name, c) => {
    const adapter = adapters[c.builder];
    expect(adapter).toBeDefined();
    expect(adapter!(c.args as Args)).toBe(c.expected);
  });

  it('leaves out, as the web does, a row whose references the lists cannot name', () => {
    const requirements = cases.cases.find((c) => c.name === 'requirementsToCsv')!;
    const lines = requirements.expected.split('\r\n').filter((line) => line !== '');
    // header + three rows kept of seven (the other four name a teacher, group or subject the lists lack)
    expect(lines).toHaveLength(1 + 3);
  });
});
